_OPENAI_PROXY_POLICY = route_registry.openai_proxy_policy(
    registry=_PROTOCOL_ROUTE_REGISTRY,
    proxy_config=config,
)

_INTERNAL_PROTOCOL_FORWARD_HEADER = "x-vivid-fish-internal-protocol-forward"
_INTERNAL_PROTOCOL_FORWARD_SECRET = secrets.token_urlsafe(32)
_INTERNAL_PROTOCOL_FORWARD_HOSTS = frozenset({"127.0.0.1", "::1"})
_INTERNAL_LITELLM_KEY_ENV = "AI_GATEWAY_INTERNAL_LITELLM_KEY"


def _is_internal_protocol_forward(request: Request) -> bool:
    """Allow first-class protocol frontends to reuse chat routing internally.

    Anthropic and Ollama routes have already passed their own profile policy.
    Their loopback call to `/v1/chat/completions` should not add a second
    `openai.chat` permission requirement. The bypass is secret-bearing and
    loopback-only so public clients cannot opt out of OpenAI route policy.
    """
    if request.headers.get(_INTERNAL_PROTOCOL_FORWARD_HEADER) != _INTERNAL_PROTOCOL_FORWARD_SECRET:
        return False
    client = getattr(request, "client", None)
    return getattr(client, "host", None) in _INTERNAL_PROTOCOL_FORWARD_HOSTS


def _is_internal_litellm_lifecycle_request(request: Request) -> bool:
    expected = os.environ.get(_INTERNAL_LITELLM_KEY_ENV, "").strip()
    if not expected:
        return False
    auth = request.headers.get("authorization", "")
    scheme, _, token = auth.partition(" ")
    return scheme.lower() == "bearer" and secrets.compare_digest(token.strip(), expected)


def _normalize_litellm_local_model_name(value: Any) -> str:
    model = str(value or "").strip()
    if model.startswith("openai/"):
        return model.removeprefix("openai/").strip()
    return model


def _litellm_local_activation_target(
    backend: str,
    requested_model: str,
) -> LocalModelActivation:
    backend_cfg = config.get("backends", {}).get(backend, {})
    if not isinstance(backend_cfg, Mapping):
        return LocalModelActivation(
            backend=backend,
            model=requested_model,
            backend_model=requested_model,
        )
    requested = normalize_model_id(requested_model)
    for item in _service_model_records(backend_cfg):
        candidates = {
            item.get("id"),
            item.get("model_group"),
            item.get("model"),
            item.get("upstream_model"),
            item.get("activation_model"),
        }
        activation_model = str(
            item.get("activation_model")
            or item.get("model")
            or item.get("upstream_model")
            or ""
        ).strip()
        if activation_model:
            candidates.add(os.path.basename(activation_model))
        if requested in {normalize_model_id(candidate) for candidate in candidates if candidate}:
            activation_mmproj = str(
                item.get("activation_mmproj") or item.get("mmproj") or ""
            ).strip()
            activation_profile = str(item.get("activation_profile") or "").strip()
            backend_model = str(item.get("backend_model") or requested_model).strip()
            return LocalModelActivation(
                backend=backend,
                model=activation_model or requested_model,
                mmproj=activation_mmproj or None,
                profile=activation_profile or None,
                backend_model=backend_model or requested_model,
            )
    return LocalModelActivation(
        backend=backend,
        model=requested_model,
        backend_model=requested_model,
    )


def _openai_proxy_policy_decision(
    auth_context: AuthContext,
    request_path: str,
    body: bytes,
) -> PolicyDecision | None:
    spec = _OPENAI_PROXY_POLICY.get(request_path)
    if spec is None:
        return None

    model: str | None = None
    try:
        body_json = json.loads(body)
        if isinstance(body_json, Mapping) and isinstance(body_json.get("model"), str):
            model = body_json["model"]
    except Exception:
        pass

    protocol, intent = spec
    return evaluate_and_apply(
        auth_context.identity,
        make_policy_request(
            protocol=protocol,
            intent=intent,
            model=model,
            capability_exposure="default",
            capability_trust_tier="stable",
            capability_resource_tier="interactive",
        ),
    )


def _litellm_unconfigured_response() -> Response:
    return Response(
        content=json.dumps({
            "error": {
                "message": (
                    "LiteLLM execution is enabled, but the gateway service "
                    "registry has no enabled LiteLLM service with a base URL."
                ),
                "type": "service_unavailable",
                "code": "litellm_unconfigured",
            }
        }),
        status_code=503,
        media_type="application/json",
    )


def _litellm_runtime_config():
    try:
        registry = ADMIN_STORE.get_service_registry()
    except Exception as e:  # noqa: BLE001
        print(f"[proxy] LiteLLM registry lookup failed: {e}", flush=True)
        registry = None
    return litellm_runtime_from_registry(
        registry,
        env=os.environ,
    )


def _toolcall_backend_hint(service_id: str) -> str:
    """Derive the backend hint string used for advisory messages.

    Prefers the stored ``preset`` field in config["backends"][service_id] when
    present (e.g. "vllm", "ollama", "tabbyapi").  Falls back to the service_id
    itself — many operators name their service after the backend (e.g. "vllm",
    "tabby").  The detection module does case-insensitive substring matching so
    either form works.
    """
    if not service_id:
        return "unknown"
    bcfg = (config.get("backends") or {}).get(service_id) or {}
    return str(bcfg.get("preset") or service_id)


def _transform_specs(raw: Any) -> list[str | dict[str, Any]]:
    """Keep valid named or inline declarative transform specs from service data."""
    return _pure_transform_specs(raw)


def _per_backend_transform_specs(
    service_id: str,
    *,
    model_name: str = "",
    runtime_config: Mapping[str, Any] | None = None,
) -> list[str | dict[str, Any]]:
    """Return service then exact-model transform specs from backend config data.

    Inline mappings are instances of the fixed transform primitive vocabulary;
    strings select reviewed named built-ins. Model attachments are considered
    only for an exact public id/model_group match, so a shared upstream model
    cannot inherit another public model's policy.
    """
    source = runtime_config if runtime_config is not None else config
    return _pure_per_backend_transform_specs(
        service_id,
        model_name=model_name,
        runtime_config=source,
    )


class ModelPolicySchemaError(ValueError):
    """A local models collection is not declared at the supported policy version."""


def _alias_policy_configuration_response(error: AliasPolicyResolutionError) -> Response:
    return openai_error_response(
        f"Gateway alias policy is unavailable: {error}",
        status_code=503,
        error_type="service_unavailable",
        code="alias_policy_unavailable",
    )


def _model_policy_schema_configuration_response(error: ModelPolicySchemaError) -> Response:
    return openai_error_response(
        f"Gateway model policy configuration is unavailable: {error}",
        status_code=503,
        error_type="service_unavailable",
        code="model_policy_schema_unavailable",
    )


def _model_policy_schema_error(service_id: str) -> ModelPolicySchemaError | None:
    """Preflight a local models collection without inferring model intent."""
    backends = config.get("backends") if isinstance(config.get("backends"), Mapping) else {}
    service_cfg = backends.get(service_id)
    if not isinstance(service_cfg, Mapping):
        return ModelPolicySchemaError(f"service {service_id!r} is not configured")
    version = service_cfg.get("model_policy_schema_version")
    if (
        isinstance(version, int)
        and not isinstance(version, bool)
        and version == service_registry.MODEL_POLICY_SCHEMA_VERSION
    ):
        return None
    found = "missing" if version is None else repr(version)
    return ModelPolicySchemaError(
        f"service {service_id!r} models use schema {found}; expected "
        f"{service_registry.MODEL_POLICY_SCHEMA_VERSION}"
    )


def _resolve_request_target(
    requested_model: Any,
    *,
    service_id: str | None = None,
    required: bool = False,
    aliases_only: bool = False,
    runtime_config: Mapping[str, Any] | None = None,
) -> ResolvedRequestTarget | None:
    """Resolve a public model to one service-scoped base and alias overlay.

    Physical upstream/activation names intentionally do not participate in this
    lookup: a shared filename is routing data, never logical policy identity.
    """
    source = runtime_config if runtime_config is not None else config
    return _pure_resolve_request_target(
        requested_model,
        service_id=service_id,
        required=required,
        aliases_only=aliases_only,
        runtime_config=source,
    )


def _prepare_resolved_openai_request(
    body: Mapping[str, Any],
    *,
    request_path: str,
    target: ResolvedRequestTarget | None,
    execution_service_id: str = "",
    runtime_config: Mapping[str, Any] | None = None,
) -> tuple[Response | None, Mapping[str, Any], bytes | None]:
    """Apply the one request-policy pipeline, then generic reasoning handling."""
    prepared = copy.deepcopy(dict(body))
    if target is None:
        return None, prepared, None
    specs = _per_backend_transform_specs(execution_service_id, runtime_config=runtime_config)
    specs.extend(target.base_transform_specs)
    specs.extend(target.alias_overlay_specs)
    if specs:
        prepared = _run_request_pipeline(
            specs,
            prepared,
            _TransformContext(),
            _TRANSFORM_REGISTRY,
        )
    if request_path == "/v1/chat/completions":
        source = runtime_config if runtime_config is not None else config
        reasoning_error = _ReasoningEffortTransform(source.get("reasoning") or {}).apply(prepared)
        if reasoning_error:
            return Response(
                content=json.dumps({"error": {
                    "message": reasoning_error,
                    "type": "invalid_request_error",
                    "param": "reasoning_effort",
                    "code": "invalid_value",
                }}),
                status_code=400,
                media_type="application/json",
            ), prepared, None
    return None, prepared, None


def _litellm_gateway_metadata(
    auth_context: AuthContext,
    *,
    request_path: str,
    service_id: str = "",
    delegated_litellm_api_key: str = "",
) -> dict[str, str]:
    metadata = {
        "execution": "litellm",
        "request-path": request_path,
        "profile": _profile_source_id(auth_context),
    }
    if service_id:
        metadata["service-id"] = service_id
    if delegated_litellm_api_key:
        metadata["auth-source"] = "litellm"
        metadata["litellm-key-prefix"] = hash_api_key(delegated_litellm_api_key)[:18]
        return metadata
    identity = auth_context.identity
    if identity is not None:
        metadata["app"] = str(identity.name)
        metadata["key-prefix"] = str(identity.key_hash or "")[:18]
    return metadata


def _start_litellm_route_receipt(
    *,
    request_path: str,
    auth_context: AuthContext,
    requested_model: str,
    protocol: str | None = None,
    intent: str | None = None,
    delegated_litellm_api_key: str = "",
    parent_request_id: str = "",
) -> RouteReceipt:
    if protocol is None or intent is None:
        protocol, intent = _OPENAI_PROXY_POLICY.get(
            request_path,
            ("openai.chat", "chat.generate"),
        )
    profile = _profile_for_auth_context(auth_context)
    if parent_request_id:
        receipt = RouteReceipt(
            protocol=protocol,
            path=request_path,
            intent=intent,
            backend="litellm",
            requested_model=requested_model,
            parent_request_id=parent_request_id,
            visibility="internal",
        )
        receipt.set_policy_decision("allowed", source="gateway:trusted-loopback")
        receipt.metadata["execution_backend"] = "litellm"
        return receipt
    if delegated_litellm_api_key:
        receipt = RouteReceipt(
            protocol=protocol,
            path=request_path,
            intent=intent,
            backend="litellm",
            requested_model=requested_model,
            app_profile="litellm",
            app_id=None,
            api_key_name="litellm-virtual-key",
            visibility=profile.status_visibility.level,
        )
        receipt.set_policy_decision("allowed", source="litellm:virtual-key")
        receipt.metadata.update(
            {
                "execution_backend": "litellm",
                "auth_source": "litellm",
            }
        )
        return receipt
    receipt = RouteReceipt(
        protocol=protocol,
        path=request_path,
        intent=intent,
        backend="litellm",
        requested_model=requested_model,
        app_profile=profile.id,
        app_id=auth_context.identity.app_id if auth_context.identity else None,
        owner_key_hash=auth_context.identity.key_hash if auth_context.identity else None,
        api_key_name=auth_context.identity.name if auth_context.identity else None,
        visibility=profile.status_visibility.level,
    )
    receipt.set_policy_decision("allowed", source="gateway:profile")
    receipt.metadata.update({"execution_backend": "litellm"})
    return receipt


_LITELLM_METADATA_MAX_VALUE_LENGTH = 128

# Deliberately excludes "x-litellm-call-id" (an opaque upstream-assigned id
# with no length bound of its own — admin_stage_list_bypass/
# admin_exposes_unbounded_call_id_length in the reliability audit) and
# "x-litellm-model-api-base" (the upstream URL LiteLLM actually dispatched
# to, which can carry embedded userinfo/query credentials —
# admin_exposes_model_api_base in the same audit). Every remaining key is a
# small, bounded scalar fact (a model name/group, a cost, a duration, a
# retry/fallback count) safe to admin-promote as-is.
_LITELLM_METADATA_ADMIN_SAFE_KEYS = (
    "x-litellm-model-id",
    "x-litellm-model-group",
    "x-litellm-response-cost",
    "x-litellm-response-duration-ms",
    "x-litellm-attempted-retries",
    "x-litellm-attempted-fallbacks",
)


def _attach_litellm_response_metadata(
    receipt: RouteReceipt,
    headers: Mapping[str, str],
) -> None:
    facts: dict[str, str] = {}
    lowered = {key.lower(): value for key, value in headers.items()}
    for key in _LITELLM_METADATA_ADMIN_SAFE_KEYS:
        value = lowered.get(key)
        if value:
            facts[key.removeprefix("x-litellm-").replace("-", "_")] = (
                str(value)[:_LITELLM_METADATA_MAX_VALUE_LENGTH]
            )
    if facts:
        receipt.metadata["litellm"] = facts


def _normalize_litellm_error_envelope(
    payload: dict[str, Any],
    *,
    status_code: int,
) -> None:
    error = payload.get("error")
    if not isinstance(error, dict):
        return

    def is_empty(value: Any) -> bool:
        return value is None or value == "" or value == "None"

    message = str(error.get("message") or "")
    if "Invalid model name passed" in message:
        if is_empty(error.get("type")):
            error["type"] = "invalid_request_error"
        if is_empty(error.get("param")):
            error["param"] = "model"
        if is_empty(error.get("code")) or str(error.get("code")).isdigit():
            error["code"] = "model_not_found"
        return

    if is_empty(error.get("type")):
        error["type"] = "invalid_request_error" if 400 <= status_code < 500 else "api_error"
    if is_empty(error.get("param")):
        error["param"] = None


def _record_internal_hop_receipt(
    *,
    request_path: str,
    parent_request_id: str,
    body: Mapping[str, Any] | None,
    status_code: int | None,
    terminal_reason: str,
) -> None:
    """Record a small internal-gateway-hop receipt linked to the outer request.

    The internal LiteLLM hop (``/internal/litellm/...``) runs in the same
    process but is reached through a second, independent HTTP round trip via
    LiteLLM's sidecar — it never receives the outer route's ``RouteReceipt``
    object, only the forwarded ``X-AI-Gateway-Request-Id`` string. Recording
    a second, small receipt here — linked via ``parent_request_id`` rather
    than overwriting the outer receipt's row — keeps internal_ingress/
    backend_egress/terminal facts queryable through the existing receipt
    store without a parallel observability subsystem or cross-process state.
    A missing/unknown parent id (a caller that bypassed the outer route, or
    an older LiteLLM build) is a no-op — there is nothing to link to.
    """
    if not parent_request_id:
        return
    receipt = RouteReceipt(
        protocol="openai.chat",
        path=request_path,
        intent="chat.generate",
        parent_request_id=parent_request_id,
        visibility="internal",
    )
    record_request_shape_stage(
        receipt.metadata,
        "internal_ingress",
        body,
    )
    record_request_shape_stage(
        receipt.metadata,
        "backend_egress",
        body,
        extra={"status_code": status_code} if status_code is not None else None,
    )
    record_request_shape_stage(
        receipt.metadata,
        "terminal",
        body,
        extra={"terminal_reason": terminal_reason},
    )
    receipt.metadata["terminal_reason"] = terminal_reason
    receipt.finish(
        "cancelled" if terminal_reason == "cancelled"
        else "succeeded" if terminal_reason == "completed"
        else "failed"
    )
    try:
        receipt_store.record(receipt)
    except Exception as e:  # noqa: BLE001
        print(f"[proxy] Could not record internal-hop receipt: {e}", flush=True)


def _forward_query_without_client_api_key(raw_query: str) -> str:
    if not raw_query:
        return ""
    pairs = [
        (key, value)
        for key, value in parse_qsl(raw_query, keep_blank_values=True)
        if key != "api_key"
    ]
    return urlencode(pairs)


def _gateway_request_id_metadata(request_id: str) -> dict[str, str]:
    return {"request-id": request_id}


def _internal_request_id_from_headers(headers: Mapping[str, str]) -> str:
    lowered = {str(key).lower(): str(value) for key, value in headers.items()}
    return lowered.get(GATEWAY_REQUEST_ID_HEADER.lower(), "")


class _OuterCancellationSpan:
    """Own one outer-route request's disconnect watcher and cancellation handle.

    Built once per request, after the request body has already been fully
    consumed, so its ``RequestDisconnectWatcher`` is the sole consumer of the
    ASGI receive channel while it is alive. That watcher covers pre-header
    dispatch (``dispatch``) and, for a response that turns out to be
    non-streaming, the body read (``read_body``) too.

    A response that turns out to stream must hand ASGI receive over to
    Starlette's own ``StreamingResponse`` disconnect listener exclusively —
    call ``stop_watcher_for_streaming_handoff`` the moment the content type is
    known to be a stream and before constructing ``StreamingResponse``, so
    this span's background watcher task is fully torn down first and never
    runs concurrently with Starlette's. Any disconnect the watcher already
    observed up to that point is signalled immediately during the handoff;
    after that, the streaming generator's own cancellation (delivered via
    Starlette, once it sees ``http.disconnect``) is the sole remaining
    disconnect signal — report it with ``mark_stream_cancelled``.

    Registers ``request_id`` in the shared ``CancellationRegistry`` and wires
    every disconnect this span itself observes to ``signal()``, so the
    internal gateway hop's reader (reached through LiteLLM's forwarded
    ``X-AI-Gateway-Request-Id``) wakes even though it has no direct view of
    this ASGI connection. ``aclose`` releases the registry handle and closes
    the watcher (a no-op if already stopped) on every terminal path.
    """

    def __init__(self, request_id: str, *, receive: Callable[[], Awaitable[Mapping[str, Any]]]) -> None:
        self.request_id = request_id
        self._handle = cancellation_registry().register(request_id)
        self.token = self._handle.token
        self.watcher = RequestDisconnectWatcher(receive)

    async def _signal(self) -> None:
        """Signal the registry immediately — the sole place this span does so.

        Passed as ``on_signal`` to the transport helpers below so the signal
        fires the instant a disconnect/cancel wins its race, strictly before
        those helpers begin any response/client teardown that can block.
        Cross-hop propagation must never wait behind local cleanup.
        """
        cancellation_registry().signal(self.request_id)

    async def dispatch(self, execution_request: "LlmExecutionRequest"):
        """Send the upstream request, racing pre-header client disconnect/cancel.

        Raises ``ClientDisconnectedBeforeHeaders`` if the client disconnects,
        or if a cross-hop cancel (``cancellation_registry().signal``) fires,
        before upstream response headers arrive. Both ``disconnect_watcher``
        (local ASGI disconnect) and ``cancellation_token`` (the registry
        token — the load-bearing signal for a hop with no local downstream
        client, e.g. behind LiteLLM) race the same pre-header wait, matching
        ``read_body`` below, which already races both for the body-read
        phase. Signalling happens inside ``send_llm_execution_request`` via
        ``on_signal`` — before it cancels the in-flight send or closes the
        client — so any internal-hop reader racing the same id wakes
        immediately rather than after teardown.
        """
        try:
            return await send_llm_execution_request(
                execution_request,
                disconnect_watcher=self.watcher,
                cancellation_token=self.token,
                on_signal=self._signal,
            )
        except BaseException:
            await self.aclose()
            raise

    async def read_body(self, client: httpx.AsyncClient, response: httpx.Response) -> bytes | None:
        """Read a non-stream response body, signalling on disconnect/cancel.

        Delegates to ``read_llm_response_body``, which races this span's
        watcher and cancellation token internally and calls ``on_signal``
        the instant either fires — before it cancels the read or closes the
        response/client. No separate poll, no pre-wait snapshot for callers
        to go stale against.
        """
        try:
            return await read_llm_response_body(
                client,
                response,
                disconnect_watcher=self.watcher,
                cancellation_token=self.token,
                on_signal=self._signal,
            )
        except BaseException:
            await self.aclose()
            raise

    async def stop_watcher_for_streaming_handoff(self) -> None:
        """Retire this span's watcher before Starlette owns ASGI receive.

        Must be called once the response is known to stream and before
        ``StreamingResponse`` is constructed — never while it, or any other
        consumer, might also be calling ``receive()``. Signals immediately if
        the watcher already caught a disconnect (pre-header or the brief
        window between headers and the streaming decision); otherwise this is
        silent handoff, since a normal in-flight request is not a disconnect.
        """
        already_disconnected = self.watcher.disconnected
        await self.watcher.aclose()
        if already_disconnected:
            cancellation_registry().signal(self.request_id)

    def mark_stream_cancelled(self) -> None:
        """Signal the registry that the streaming generator was cancelled.

        Call from the streaming generator's own ``except asyncio.CancelledError``
        handling — once ``stop_watcher_for_streaming_handoff`` has run,
        Starlette's disconnect listener (racing the same ASGI receive
        channel) is the sole remaining source of a mid-stream disconnect
        signal, and it surfaces as this generator being cancelled by
        Starlette's task group. There is no separate poll.
        """
        cancellation_registry().signal(self.request_id)

    async def aclose(self) -> None:
        await self.watcher.aclose()
        self._handle.release()

    async def __aenter__(self) -> "_OuterCancellationSpan":
        return self

    async def __aexit__(self, *exc_info: object) -> None:
        await self.aclose()


async def _forward_current_loaded_openai_request(
    request: Request,
    *,
    request_path: str,
    auth_context: AuthContext,
    body_json: Mapping[str, Any],
    enforce_gateway_policy: bool = True,
    request_id: str = "",
) -> Response:
    requested_alias = body_json.get("model")
    try:
        logical_target = _resolve_request_target(
            requested_alias,
            required=True,
            aliases_only=True,
        )
    except AliasPolicyResolutionError as error:
        return _alias_policy_configuration_response(error)
    schema_error = _model_policy_schema_error(logical_target.logical_service_id)
    if schema_error is not None:
        return _model_policy_schema_configuration_response(schema_error)
    body_for_backend: Mapping[str, Any] = body_json
    if request_path == "/v1/chat/completions":
        try:
            extension_result = validate_chat_completions_extensions(body_json)
        except ExtensionError as e:
            return _extension_validation_error_response({"extensions": str(e)})
        if not extension_result.ok:
            return _extension_validation_error_response(extension_result.rejected)
        body_for_backend = extension_result.request

    # Begin after the pure alias/extension checks but before resolving the
    # active backend: resolution probes the backend and may wait on network I/O.
    is_internal_hop = bool(request_id)
    profile = _profile_for_auth_context(auth_context)
    receipt = RouteReceipt(
        protocol="openai.chat",
        path=request_path,
        intent="chat.generate",
        requested_model=str(requested_alias) if requested_alias else None,
        resolved_model=logical_target.base_model_id,
        parent_request_id=request_id if is_internal_hop else None,
        app_profile=None if is_internal_hop else profile.id,
        app_id=None if is_internal_hop or auth_context.identity is None else auth_context.identity.app_id,
        owner_key_hash=None if is_internal_hop or auth_context.identity is None else auth_context.identity.key_hash,
        api_key_name=None if is_internal_hop or auth_context.identity is None else auth_context.identity.name,
        visibility="internal" if is_internal_hop else profile.status_visibility.level,
        stream=bool(body_for_backend.get("stream")),
        effective_output_limit=effective_output_limit(body_for_backend),
    )
    receipt.metadata.update({"execution_backend": "current-loaded"})
    if is_internal_hop:
        record_request_shape_stage(receipt.metadata, "internal_ingress", body_json)
    else:
        record_request_shape_stage(receipt.metadata, "accepted", body_for_backend)
    terminal_body = body_for_backend

    def _record_current_loaded_terminal(_receipt: RouteReceipt, terminal_reason: str) -> None:
        record_request_shape_stage(
            receipt.metadata, "terminal", terminal_body,
            extra={"terminal_reason": terminal_reason},
        )
    owner = ReceiptLifecycleOwner(receipt, on_terminal=_record_current_loaded_terminal)
    async with owner:
        target, target_error = await _current_loaded_llm_target(
            auth_context,
            enforce_gateway_policy=enforce_gateway_policy,
        )
        if target_error is not None:
            owner.report(status="failed", reason="failed")
            return target_error
        assert target is not None
    # These are post-acceptance resolution facts.  finalize() merges them into
    # the same in-progress row without replacing immutable acceptance facts.
        receipt.backend = target.backend
        receipt.resolved_model = target.model

        body = copy.deepcopy(dict(body_for_backend))
        body.pop("_vf_requested_model", None)
        body["model"] = target.model
        policy_error, body, execution_body = _prepare_resolved_openai_request(
            body,
            request_path=request_path,
            target=logical_target,
            execution_service_id=target.backend,
        )
        terminal_body = body
        if policy_error is not None:
            owner.report(status="failed", reason="failed")
            return policy_error
        query = _forward_query_without_client_api_key(request.url.query)
        url = f"{target.host}{request_path}"
        if query:
            url = f"{url}?{query}"

        headers = prepare_downstream_headers(
            request.headers,
            auth_context,
            target.backend,
            request_path,
        )
        headers.setdefault("content-type", "application/json")
        headers.setdefault("accept", "application/json")

        if execution_body is None:
            execution_body = json.dumps(body).encode()
        execution_request = LlmExecutionRequest(
            method=request.method,
            url=url,
            headers=headers,
            body=execution_body,
            read_timeout=UPSTREAM_READ_TIMEOUT,
        )

        record_request_shape_stage(
            receipt.metadata, "outer_egress", body,
            extra={"body_bytes": request_body_byte_count(execution_body)},
        )

        cancellation_span = _OuterCancellationSpan(
            request_id or new_request_id(), receive=request.receive
        )

        try:
            try:
                client, resp = await cancellation_span.dispatch(execution_request)
            except ClientDisconnectedBeforeHeaders:
                await cancellation_span.aclose()
                owner.report(status="cancelled", reason="cancelled")
                return Response(status_code=499)
            content_type = resp.headers.get("content-type", "") or "application/json"
            record_request_shape_stage(
                receipt.metadata, "backend_egress", body,
                extra={"status_code": resp.status_code},
            )
            excluded = ("content-length", "transfer-encoding", "content-type", "x-ai-gateway-request-id", "x-ai-gateway-receipt-id")
            response_headers = {
                k: v for k, v in resp.headers.items() if k.lower() not in excluded
            }
            response_headers["X-AI-Gateway-LLM-Execution"] = "current-loaded"
            response_headers["X-AI-Gateway-Request-Id"] = receipt.request_id
            response_headers["X-AI-Gateway-Receipt-Id"] = receipt.request_id
            response_headers["X-AI-Gateway-Backend"] = target.backend
            response_headers["X-AI-Gateway-Resolved-Model"] = target.model

            _tc_backend_hint = _toolcall_backend_hint(target.backend)
            _tc_had_tools = (
                request_path == "/v1/chat/completions"
                and _request_had_tools(body)
            )

            if "text/event-stream" in content_type:
                _tc_detector = _ToolcallStreamDetector(
                    had_tools=_tc_had_tools,
                    backend_hint=_tc_backend_hint,
                )
                # Hand ASGI receive over to Starlette's own disconnect listener
                # before it exists: this span's watcher must never run
                # concurrently with StreamingResponse's receive loop.
                await cancellation_span.stop_watcher_for_streaming_handoff()

                async def stream_response():
                    try:
                        async for chunk in _tc_detector.wrap(
                            iter_llm_response_bytes(
                                client,
                                resp,
                                cancellation_token=cancellation_span.token,
                                on_signal=cancellation_span._signal,
                            )
                        ):
                            if request_path == "/v1/chat/completions":
                                chunk = _normalize_chat_completion_sse_chunk(chunk)
                            yield chunk
                    except asyncio.CancelledError:
                        cancellation_span.mark_stream_cancelled()
                        raise
                    else:
                        owner.report(
                            status="succeeded" if 200 <= resp.status_code < 400 else "failed",
                            reason="completed" if 200 <= resp.status_code < 400 else "failed",
                        )
                    finally:
                        _tc_advisory = _tc_detector.advisory()
                        if _tc_advisory:
                            import logging as _logging
                            _logging.getLogger("gateway.toolcall").warning(
                                "event=toolcall.unlifted backend=%s family=%s remediation=%r",
                                _tc_backend_hint,
                                _tc_detector.detected_family,
                                _tc_advisory,
                            )
                        await resp.aclose()
                        await client.aclose()
                        await cancellation_span.aclose()

                return StreamingResponse(
                    owner.handoff_stream(stream_response()),
                    status_code=resp.status_code,
                    headers=response_headers,
                    media_type=content_type,
                )

            content = await cancellation_span.read_body(client, resp)
            was_cancelled = cancellation_span.token.cancelled
            await cancellation_span.aclose()
            if content is None:
                owner.report(
                    status="cancelled",
                    reason="cancelled" if was_cancelled else "disconnected",
                )
                return Response(status_code=499)
            await close_llm_response(client, resp)
            if "application/json" in content_type:
                try:
                    response_json = json.loads(content)
                    if isinstance(response_json, dict):
                        if 200 <= resp.status_code < 300 and request_path == "/v1/chat/completions":
                            _normalize_chat_completion_payload(response_json)
                            _normalize_toolcall_args(response_json)
                            _normalize_toolcall_finish_reason(response_json)
                            # Per-backend response transforms (data-driven; see ENGINE_KNOWLEDGE_BOUNDARY.md).
                            _resp_tx = _per_backend_transform_specs(target.backend)
                            if _resp_tx:
                                response_json = _run_response_pipeline(
                                    _resp_tx, response_json, _TransformContext(), _TRANSFORM_REGISTRY,
                                )
                            _tc_family = _detect_unlifted_toolcalls(response_json, _tc_had_tools)
                            if _tc_family:
                                _tc_advisory = _toolcall_advisory_for_backend(_tc_backend_hint, _tc_family)
                                import logging as _logging
                                _logging.getLogger("gateway.toolcall").warning(
                                    "event=toolcall.unlifted backend=%s family=%s remediation=%r",
                                    _tc_backend_hint,
                                    _tc_family,
                                    _tc_advisory,
                                )
                                response_headers["x-gateway-toolcall-advisory"] = _tc_advisory
                        content = json.dumps(response_json).encode()
                except (json.JSONDecodeError, UnicodeDecodeError):
                    pass
            owner.report(
                reason="completed" if 200 <= resp.status_code < 400 else "failed",
                status="succeeded" if 200 <= resp.status_code < 400 else "failed",
            )
            return Response(
                content=content,
                status_code=resp.status_code,
                headers=response_headers,
                media_type=content_type,
            )
        except httpx.TimeoutException:
            await cancellation_span.aclose()
            owner.report(status="failed", reason="idle_timeout")
            return openai_error_response(
                "Current loaded LLM request timed out.",
                status_code=504,
                error_type="api_error",
                code="timeout",
            )
        except httpx.ConnectError:
            await cancellation_span.aclose()
            owner.report(status="failed", reason="connect_error")
            response = openai_error_response(
                f"Active backend {target.backend!r} is unavailable.",
                status_code=503,
                error_type="service_unavailable",
                code="backend_unavailable",
            )
            response.headers["Retry-After"] = "10"
            return response


async def _forward_litellm_proxy_request(
    request: Request,
    *,
    request_path: str,
    auth_context: AuthContext,
    body_json: Mapping[str, Any],
    runtime_config,
    requested_embedding_dimensions: int | None = None,
    delegated_litellm_api_key: str = "",
    parent_request_id: str = "",
    activate_local_target: bool = False,
) -> Response:
    model_name = body_json.get("model")
    if not isinstance(model_name, str) or not model_name:
        return openai_error_response(
            "Missing required parameter: 'model'.",
            status_code=400,
            param="model",
            code="missing_required_parameter",
        )

    remote_provider = provider_execution.provider_for_model(ADMIN_STORE.get_service_registry(), model_name)
    if remote_provider is not None:
        identity = auth_context.identity
        return await provider_execution.execute_paid_litellm(
            request, request_path=request_path, body=body_json,
            provider=remote_provider, profile=_profile_for_auth_context(auth_context),
            runtime=runtime_config, ledger_path=ADMIN_DB_PATH.parent / "provider_spend.db",
            admin_db_path=ADMIN_DB_PATH,
            app_id=identity.app_id if identity else None,
            app_name=identity.name if identity else None,
            delegated=bool(delegated_litellm_api_key),
            paid_fallback=bool(getattr(request.state, "paid_provider_fallback", False)),
            requested_model=getattr(request.state, "provider_requested_model", None),
        )

    try:
        logical_target = _resolve_request_target(model_name, aliases_only=True)
    except AliasPolicyResolutionError as error:
        return _alias_policy_configuration_response(error)

    if _profile_target_activation(auth_context) == "existing_only":
        current_loaded_decision = await _current_loaded_model_policy_decision(
            auth_context,
            requested_model=model_name,
        )
        if current_loaded_decision is not None and current_loaded_decision.denied:
            return _policy_denied_response(current_loaded_decision)

    runtime = runtime_config
    if not runtime.enabled:
        return _litellm_unconfigured_response()

    receipt = _start_litellm_route_receipt(
        request_path=request_path,
        auth_context=auth_context,
        requested_model=model_name,
        delegated_litellm_api_key=delegated_litellm_api_key,
        parent_request_id=parent_request_id,
    )
    body_for_litellm = body_json
    if request_path == "/v1/chat/completions":
        try:
            extension_result = validate_chat_completions_extensions(body_json)
        except ExtensionError as e:
            return _extension_validation_error_response({"extensions": str(e)})
        if not extension_result.ok:
            return _extension_validation_error_response(extension_result.rejected)
        body_for_litellm = extension_result.request
    if (
        request_path == "/v1/embeddings"
        and requested_embedding_dimensions is not None
    ):
        body_for_litellm = dict(body_for_litellm)
        body_for_litellm.pop("dimensions", None)

    body = json.dumps(dict(body_for_litellm)).encode()
    receipt.resolved_model = (
        str(body_for_litellm.get("model"))
        if isinstance(body_for_litellm.get("model"), str)
        else None
    )
    receipt.stream = bool(body_for_litellm.get("stream"))
    receipt.effective_output_limit = effective_output_limit(body_for_litellm)
    receipt.metadata["request_shape"] = request_shape_fields(body_for_litellm)
    receipt.metadata["request_shape"]["body_bytes"] = request_body_byte_count(body)
    record_request_shape_stage(
        receipt.metadata,
        "accepted",
        body_json,
    )
    record_request_shape_stage(
        receipt.metadata,
        "outer_egress",
        body_for_litellm,
        extra={"body_bytes": request_body_byte_count(body)},
    )
    gateway_metadata = _litellm_gateway_metadata(
        auth_context,
        request_path=request_path,
        service_id=runtime.service_id,
        delegated_litellm_api_key=delegated_litellm_api_key,
    )
    gateway_metadata.update(_gateway_request_id_metadata(receipt.request_id))
    read_timeout = (
        EMBEDDINGS_TIMEOUT
        if request_path == "/v1/embeddings"
        else UPSTREAM_READ_TIMEOUT
    )
    execution_request = LlmExecutionRequest(
        method=request.method,
        url=litellm_url(
            base_url=runtime.base_url,
            path=request_path,
            query=request.url.query,
        ),
        headers=litellm_headers(
            request.headers,
            api_key=runtime.api_key,
            gateway_metadata=gateway_metadata,
            delegated_api_key=delegated_litellm_api_key,
        ),
        body=body,
        read_timeout=read_timeout,
    )

    terminal_body = body_for_litellm

    def _record_litellm_terminal(_receipt: RouteReceipt, terminal_reason: str) -> None:
        record_request_shape_stage(
            receipt.metadata,
            "terminal",
            terminal_body,
            extra={"terminal_reason": terminal_reason},
        )

    # The owner admits after auth, policy, and pure request preparation, but
    # before activation, connection, or the disconnect watcher can await.
    owner = ReceiptLifecycleOwner(receipt, on_terminal=_record_litellm_terminal)
    async with owner:
        if activate_local_target:
            activation_error = await _activate_prepared_litellm_local_target(
                auth_context,
                requested_model=model_name,
                enforce_gateway_policy=not bool(delegated_litellm_api_key),
            )
            if activation_error is not None:
                owner.report(status="failed", reason="failed")
                return activation_error

        cancellation_span = _OuterCancellationSpan(receipt.request_id, receive=request.receive)

        try:
            client, resp = await cancellation_span.dispatch(execution_request)
        except ClientDisconnectedBeforeHeaders:
            await cancellation_span.aclose()
            owner.report(status="cancelled", reason="cancelled")
            return Response(status_code=499)
        except httpx.TimeoutException:
            await cancellation_span.aclose()
            receipt.add_warning("LiteLLM execution timed out")
            owner.report(status="failed", reason="idle_timeout")
            return Response(
                content=json.dumps({"detail": "Request timeout"}),
                status_code=504,
                media_type="application/json",
            )
        except httpx.ConnectError:
            await cancellation_span.aclose()
            receipt.add_warning("LiteLLM execution backend is unavailable")
            owner.report(status="failed", reason="connect_error")
            return Response(
                content=json.dumps({
                    "error": {
                        "message": "LiteLLM execution backend is unavailable.",
                        "type": "service_unavailable",
                        "code": "backend_unavailable",
                    }
                }),
                status_code=503,
                media_type="application/json",
                headers={"Retry-After": "10"},
            )
        content_type = resp.headers.get("content-type", "") or "application/json"
        excluded = ("content-length", "transfer-encoding", "content-type", "x-ai-gateway-request-id", "x-ai-gateway-receipt-id")
        response_headers = {
            k: v for k, v in resp.headers.items() if k.lower() not in excluded
        }
        response_headers["X-AI-Gateway-LLM-Execution"] = "litellm"
        response_headers["X-AI-Gateway-Request-Id"] = receipt.request_id
        response_headers["X-AI-Gateway-Receipt-Id"] = receipt.request_id
        _attach_litellm_response_metadata(receipt, resp.headers)
        record_request_shape_stage(
            receipt.metadata,
            "backend_egress",
            body_for_litellm,
            extra={"status_code": resp.status_code},
        )

        # Derive backend hint for toolcall advisory (preset id or service id).
        _tc_backend_hint = _toolcall_backend_hint(runtime.service_id)
        _tc_had_tools = (
            request_path == "/v1/chat/completions"
            and _request_had_tools(dict(body_json))
        )

        if "text/event-stream" in content_type:
            _tc_detector = _ToolcallStreamDetector(
                had_tools=_tc_had_tools,
                backend_hint=_tc_backend_hint,
            )
            # Hand ASGI receive over to Starlette's own disconnect listener
            # before it exists: this span's watcher must never run
            # concurrently with StreamingResponse's receive loop.
            await cancellation_span.stop_watcher_for_streaming_handoff()

            async def stream_response():
                try:
                    async for chunk in _tc_detector.wrap(
                        iter_llm_response_bytes(
                            client,
                            resp,
                            cancellation_token=cancellation_span.token,
                            on_signal=cancellation_span._signal,
                        )
                    ):
                        if request_path == "/v1/chat/completions":
                            chunk = _normalize_chat_completion_sse_chunk(chunk)
                        yield chunk
                except asyncio.CancelledError:
                    cancellation_span.mark_stream_cancelled()
                    raise
                else:
                    owner.report(
                        status="succeeded" if 200 <= resp.status_code < 400 else "failed",
                        reason="completed" if 200 <= resp.status_code < 400 else "failed",
                    )
                finally:
                    # Emit toolcall advisory via log at stream close.
                    _tc_advisory = _tc_detector.advisory()
                    if _tc_advisory:
                        import logging as _logging
                        _logging.getLogger("gateway.toolcall").warning(
                            "event=toolcall.unlifted backend=%s family=%s remediation=%r",
                            _tc_backend_hint,
                            _tc_detector.detected_family,
                            _tc_advisory,
                        )
                    await resp.aclose()
                    await client.aclose()
                    await cancellation_span.aclose()

            return StreamingResponse(
                owner.handoff_stream(stream_response()),
                status_code=resp.status_code,
                headers=response_headers,
                media_type=content_type,
            )

        try:
            content = await cancellation_span.read_body(client, resp)
        except httpx.TimeoutException:
            await cancellation_span.aclose()
            receipt.add_warning("LiteLLM execution timed out")
            owner.report(status="failed", reason="idle_timeout")
            return Response(
                content=json.dumps({"detail": "Request timeout"}),
                status_code=504,
                media_type="application/json",
            )
        except httpx.ConnectError:
            await cancellation_span.aclose()
            receipt.add_warning("LiteLLM execution backend is unavailable")
            owner.report(status="failed", reason="connect_error")
            return Response(
                content=json.dumps({
                    "error": {
                        "message": "LiteLLM execution backend is unavailable.",
                        "type": "service_unavailable",
                        "code": "backend_unavailable",
                    }
                }),
                status_code=503,
                media_type="application/json",
                headers={"Retry-After": "10"},
            )
        # Terminal outcome read after the wait completes — the token is the
        # single source of truth here too, so a cancellation observed during
        # the read is never overwritten by a later "succeeded" write.
        was_cancelled = cancellation_span.token.cancelled
        await cancellation_span.aclose()
        if content is None:
            terminal_reason = "cancelled" if was_cancelled else "disconnected"
            owner.report(status="cancelled", reason=terminal_reason)
            return Response(status_code=499)
        await close_llm_response(client, resp)
        if "application/json" in content_type:
            try:
                response_json = json.loads(content)
                if isinstance(response_json, dict):
                    if 200 <= resp.status_code < 300:
                        if request_path == "/v1/chat/completions":
                            # Step 4a: delegate to the registered transform function.
                            _normalize_chat_completion_payload(response_json)
                            # §6: structural normalization (args-stringify + finish-reason repair).
                            _normalize_toolcall_args(response_json)
                            _normalize_toolcall_finish_reason(response_json)
                            # Per-backend response transforms (data-driven; see ENGINE_KNOWLEDGE_BOUNDARY.md).
                            _resp_tx = _per_backend_transform_specs(runtime.service_id)
                            if _resp_tx:
                                response_json = _run_response_pipeline(
                                    _resp_tx, response_json, _TransformContext(), _TRANSFORM_REGISTRY,
                                )
                            # §5.2: detect unlifted tool calls and surface advisory.
                            _tc_family = _detect_unlifted_toolcalls(response_json, _tc_had_tools)
                            if _tc_family:
                                _tc_advisory = _toolcall_advisory_for_backend(_tc_backend_hint, _tc_family)
                                import logging as _logging
                                _logging.getLogger("gateway.toolcall").warning(
                                    "event=toolcall.unlifted backend=%s family=%s remediation=%r",
                                    _tc_backend_hint,
                                    _tc_family,
                                    _tc_advisory,
                                )
                                response_headers["x-gateway-toolcall-advisory"] = _tc_advisory
                        if (
                            request_path == "/v1/embeddings"
                            and requested_embedding_dimensions is not None
                        ):
                            dimensions_error = _apply_embedding_dimensions(
                                response_json,
                                requested_embedding_dimensions,
                            )
                            if dimensions_error is not None:
                                owner.report(status="failed", reason="failed")
                                return dimensions_error
                    else:
                        _normalize_litellm_error_envelope(
                            response_json,
                            status_code=resp.status_code,
                        )
                    content = json.dumps(response_json).encode()
            except (json.JSONDecodeError, UnicodeDecodeError):
                pass
        owner.report(
            status="succeeded" if 200 <= resp.status_code < 400 else "failed",
            reason="completed" if 200 <= resp.status_code < 400 else "failed",
        )
        return Response(
            content=content,
            status_code=resp.status_code,
            headers=response_headers,
            media_type=content_type,
        )


async def _handle_openai_litellm_request(
    request: Request,
    request_path: str,
) -> Response:
    """Try only fallback targets explicitly listed in the requested alias."""
    body, parse_error = parse_openai_json_body(await request.body())
    if parse_error is not None:
        # The normal handler owns authentication before request validation.
        return await _handle_openai_litellm_request_once(request, request_path)
    operation = "embeddings" if request_path == "/v1/embeddings" else "chat"
    try:
        alias = resolve_stable_alias(operation, body.get("model"))
    except stable_aliases.AliasUnavailableError:
        return await _handle_openai_litellm_request_once(request, request_path)
    request.state.provider_requested_model = str(body.get("model") or "")
    request.state.paid_provider_fallback = bool(alias and alias.skipped_engines)
    response = await _handle_openai_litellm_request_once(request, request_path)
    if alias is None or not alias.fallbacks:
        return response
    engines = ((config.get("model_aliases") or {}).get(operation) or {}).get("engines") or {}
    for engine_id, service_id in alias.fallbacks:
        if response.status_code != 429 and response.status_code < 500:
            break
        spec = engines.get(engine_id) or {}
        target = _provider_alias_model(engine_id, service_id, spec)
        request.state.paid_provider_fallback = True
        response = await _handle_openai_litellm_request_once(request, request_path, model_override=target)
    return response


def _provider_alias_model(engine_id: str, service_id: str | None, spec: Mapping[str, Any]) -> str:
    provider = providers.provider_lookup(ADMIN_STORE.get_service_registry(), str(service_id or ""))
    service = ((ADMIN_STORE.get_service_registry().get("services") or {}).get(service_id) or {})
    if provider is None or not service_registry.is_remote_provider_config(service.get("config") or {}):
        return engine_id
    model = str(spec.get("model") or engine_id)
    return model if model.startswith(provider.id + "/") else provider.id + "/" + model


async def _handle_openai_litellm_request_once(
    request: Request,
    request_path: str,
    *,
    model_override: str | None = None,
) -> Response:
    route_auth = authenticate_runtime_or_litellm_request(
        request,
        request_path,
        allow_litellm_delegation=True,
    )
    if isinstance(route_auth, Response):
        return route_auth
    auth_context = route_auth.auth_context
    is_trusted_loopback = _is_internal_protocol_forward(request)
    trusted_parent_request_id = (
        _internal_request_id_from_headers(request.headers) if is_trusted_loopback else ""
    )

    if not any(request_path.startswith(p) for p in NO_ACTIVITY_PATHS):
        state.update_activity()

    body_peek = await request.body()
    parsed_body, parse_error = parse_openai_json_body(body_peek)
    if parse_error is not None:
        return parse_error

    # Layer 1/2 aliases (gpt-4o, fast, text-embedding-3-small ...) become the
    # concrete role / model group before policy and LiteLLM see the request.
    try:
        chat_alias = None if model_override else resolve_stable_alias(
            "embeddings" if request_path == "/v1/embeddings" else "chat",
            parsed_body.get("model"),
        )
    except stable_aliases.AliasUnavailableError as exc:
        return openai_error_response(
            str(exc), status_code=400, param="model", code=exc.code,
        )
    if model_override or chat_alias is not None:
        target = model_override or _provider_alias_model(chat_alias.target, chat_alias.service, chat_alias.engine_spec or {})
        parsed_body = {**parsed_body, "model": target}
        body_peek = json.dumps(parsed_body).encode("utf-8")

    requested_embedding_dimensions: int | None = None
    if request_path == "/v1/embeddings":
        requested_embedding_dimensions, dimensions_error = (
            _requested_embedding_dimensions(parsed_body)
        )
        if dimensions_error is not None:
            return dimensions_error

    if (
        not route_auth.delegated_to_litellm
        and not is_trusted_loopback
    ):
        policy_decision = _openai_proxy_policy_decision(
            auth_context,
            request_path,
            body_peek,
        )
        if policy_decision is not None and policy_decision.denied:
            return _policy_denied_response(policy_decision)

    if (
        not route_auth.delegated_to_litellm
        and
        request_path in {"/v1/chat/completions", "/v1/completions"}
        and _is_use_loaded_model_alias(parsed_body.get("model"))
    ):
        return await _forward_current_loaded_openai_request(
            request,
            request_path=request_path,
            auth_context=auth_context,
            body_json=parsed_body,
            request_id=trusted_parent_request_id,
        )

    litellm_runtime = _litellm_runtime_config()
    litellm_body: Mapping[str, Any] = parsed_body
    prepared_local_llm = False
    remote_provider = provider_execution.provider_for_model(ADMIN_STORE.get_service_registry(), parsed_body.get("model"))
    if litellm_runtime.enabled and remote_provider is None:
        litellm_service_response = _service_availability_response(
            litellm_runtime.service_id or "litellm",
            service_label="LiteLLM",
        )
        if litellm_service_response is None and request_path in {
            "/v1/chat/completions",
            "/v1/completions",
        }:
            activation_error, litellm_body = await _prepare_litellm_local_llm_request(
                auth_context,
                request_path=request_path,
                body_json=parsed_body,
                enforce_gateway_policy=not route_auth.delegated_to_litellm,
                activate_target=False,
            )
            if activation_error is not None:
                return activation_error
            prepared_local_llm = True

    return await _forward_litellm_proxy_request(
        request,
        request_path=request_path,
        auth_context=auth_context,
        body_json=litellm_body,
        runtime_config=litellm_runtime,
        requested_embedding_dimensions=requested_embedding_dimensions,
        delegated_litellm_api_key=route_auth.delegated_litellm_api_key or "",
        parent_request_id=trusted_parent_request_id,
        activate_local_target=prepared_local_llm,
    )


async def _forward_internal_litellm_local_chat_completions(
    request: Request,
    *,
    backend: str,
) -> Response | StreamingResponse:
    if not _is_internal_litellm_lifecycle_request(request):
        return openai_error_response(
            "Internal LiteLLM lifecycle key is missing or invalid.",
            status_code=401,
            error_type="authentication_error",
            code="invalid_api_key",
        )

    backend = normalize_model_id(backend)
    upstream_base = LLM_BACKEND_HOSTS.get(backend, "").rstrip("/")
    if not upstream_base:
        return openai_error_response(
            f"Unknown local LLM backend: {backend!r}.",
            status_code=404,
            error_type="invalid_request_error",
            code="backend_not_found",
        )

    body_or_error = await _read_json_object(request)
    if isinstance(body_or_error, Response):
        return body_or_error
    body = dict(body_or_error)
    target_model = _normalize_litellm_local_model_name(body.get("model"))
    if not target_model:
        return openai_error_response(
            "Missing required parameter: 'model'.",
            status_code=400,
            param="model",
            code="missing_required_parameter",
        )
    activation = _litellm_local_activation_target(
        backend,
        target_model,
    )

    availability = _service_availability_response(backend, service_label=backend)
    if availability is not None:
        return availability
    ready = await ensure_target(
        backend,
        activation.model,
        activation.mmproj,
        profile=activation.profile,
    )
    if not ready:
        return _litellm_activation_failure_response(
            requested_model=str(body.get("model") or target_model),
            backend=backend,
            target_model=activation.model,
        )

    body["model"] = activation.backend_model or target_model
    execution_request = LlmExecutionRequest(
        method="POST",
        url=f"{upstream_base}/v1/chat/completions",
        headers={"content-type": "application/json"},
        body=json.dumps(body).encode("utf-8"),
        read_timeout=UPSTREAM_READ_TIMEOUT,
    )

    # This route runs behind LiteLLM's own httpx client, not the original
    # outer client's ASGI connection — the outer route's disconnect watchers
    # never fire here directly. The only cross-hop cancellation signal is the
    # gateway request id LiteLLM forwards via forward_client_headers_to_llm_api
    # (see gateway/litellm_substrate.py). A missing/unknown id (a caller that
    # bypassed the outer route, or an older LiteLLM build) degrades to no
    # cancellation token, matching prior behavior for this route.
    internal_request_id = _internal_request_id_from_headers(request.headers)
    cancellation_handle = (
        cancellation_registry().register(internal_request_id)
        if internal_request_id
        else None
    )
    cancellation_token = cancellation_handle.token if cancellation_handle else None

    try:
        try:
            client, resp = await send_llm_execution_request(
                execution_request, cancellation_token=cancellation_token
            )
        except ClientDisconnectedBeforeHeaders:
            _record_internal_hop_receipt(
                request_path="/v1/chat/completions",
                parent_request_id=internal_request_id,
                body=body,
                status_code=None,
                terminal_reason="cancelled",
            )
            return Response(status_code=499)
        except httpx.TimeoutException:
            _record_internal_hop_receipt(
                request_path="/v1/chat/completions",
                parent_request_id=internal_request_id,
                body=body,
                status_code=None,
                terminal_reason="idle_timeout",
            )
            return openai_error_response(
                "Local LLM request timed out.",
                status_code=504,
                error_type="api_error",
                code="timeout",
            )
        except httpx.ConnectError:
            _record_internal_hop_receipt(
                request_path="/v1/chat/completions",
                parent_request_id=internal_request_id,
                body=body,
                status_code=None,
                terminal_reason="connect_error",
            )
            response = openai_error_response(
                f"Local backend {backend!r} is unavailable.",
                status_code=503,
                error_type="service_unavailable",
                code="backend_unavailable",
            )
            response.headers["Retry-After"] = "10"
            return response

        content_type = resp.headers.get("content-type", "application/json")
        excluded = ("content-length", "transfer-encoding", "content-type")
        response_headers = {
            key: value for key, value in resp.headers.items() if key.lower() not in excluded
        }
        if body.get("stream") is True:
            async def stream_response():
                stream_error: BaseException | None = None
                try:
                    async for chunk in iter_llm_response_bytes(
                        client,
                        resp,
                        cancellation_token=cancellation_token,
                    ):
                        yield chunk
                except asyncio.CancelledError:
                    raise
                except BaseException as exc:
                    stream_error = exc
                    raise
                finally:
                    await resp.aclose()
                    await client.aclose()
                    was_cancelled = cancellation_token.cancelled if cancellation_token else False
                    _record_internal_hop_receipt(
                        request_path="/v1/chat/completions",
                        parent_request_id=internal_request_id,
                        body=body,
                        status_code=resp.status_code,
                        terminal_reason=(
                            "cancelled" if was_cancelled
                            else "read_error" if stream_error is not None
                            else "completed" if 200 <= resp.status_code < 400
                            else "failed"
                        ),
                    )
                    if cancellation_handle is not None:
                        cancellation_handle.release()

            return StreamingResponse(
                stream_response(),
                status_code=resp.status_code,
                headers=response_headers,
                media_type=content_type,
            )

        content = await read_llm_response_body(
            client,
            resp,
            cancellation_token=cancellation_token,
        )
        was_cancelled = cancellation_token.cancelled if cancellation_token else False
        if content is None:
            _record_internal_hop_receipt(
                request_path="/v1/chat/completions",
                parent_request_id=internal_request_id,
                body=body,
                status_code=resp.status_code,
                terminal_reason="cancelled" if was_cancelled else "disconnected",
            )
            return Response(status_code=499)
        await close_llm_response(client, resp)
        _record_internal_hop_receipt(
            request_path="/v1/chat/completions",
            parent_request_id=internal_request_id,
            body=body,
            status_code=resp.status_code,
            terminal_reason="completed" if 200 <= resp.status_code < 400 else "failed",
        )
        return Response(
            content=content,
            status_code=resp.status_code,
            headers=response_headers,
            media_type=content_type,
        )
    except BaseException:
        # No prior branch above owns this outcome (httpx.TimeoutException/
        # ConnectError/ClientDisconnectedBeforeHeaders are already handled)
        # — a generic exception here (backend protocol error, cancellation
        # raised directly into this coroutine, ...) must still terminalize
        # the internal-hop receipt rather than leave the request permanently
        # unresolved in the store. Re-raised unchanged after recording.
        _record_internal_hop_receipt(
            request_path="/v1/chat/completions",
            parent_request_id=internal_request_id,
            body=body,
            status_code=None,
            terminal_reason=(
                "cancelled" if (cancellation_token.cancelled if cancellation_token else False)
                else "internal_error"
            ),
        )
        raise
    finally:
        # The streaming path releases in its own generator finally (its
        # lifetime outlives this function's return); only release here for
        # every path that terminates before reaching that generator —
        # early returns above, and the non-stream path (released
        # immediately since it has no generator to defer to).
        if cancellation_handle is not None and body.get("stream") is not True:
            cancellation_handle.release()


@app.post(
    "/internal/litellm/current/v1/chat/completions",
    include_in_schema=False,
)
async def internal_litellm_current_chat_completions(request: Request):
    if not _is_internal_litellm_lifecycle_request(request):
        return openai_error_response(
            "Internal LiteLLM lifecycle key is missing or invalid.",
            status_code=401,
            error_type="authentication_error",
            code="invalid_api_key",
        )
    body_or_error = await _read_json_object(request)
    if isinstance(body_or_error, Response):
        return body_or_error
    body = dict(body_or_error)
    target_model = _normalize_litellm_local_model_name(body.get("model"))
    if target_model not in USE_LOADED_MODEL_ALIASES:
        body["model"] = USE_LOADED_MODEL_ALIAS
    else:
        body["model"] = target_model
    return await _forward_current_loaded_openai_request(
        request,
        request_path="/v1/chat/completions",
        auth_context=NO_AUTH_CONTEXT,
        body_json=body,
        enforce_gateway_policy=False,
        request_id=_internal_request_id_from_headers(request.headers),
    )


